/**
 * Sheet-driven overrides merged on top of the harvested product details.
 *
 * Generated by `data/tools/catalog_xlsx.py import` from the extra Excel
 * columns (gallery_urls, colors, fabrics, dimensions, materials). Keys are
 * catalogue product ids; every list is optional and may be empty.
 */
export type CatalogOverride = {
  /** Extra gallery images — absolute https URLs or PRODUCT_IMAGE_BASE-relative paths. */
  gallery?: string[];
  /** Colour swatches. A name that already exists on the product is updated in place. */
  colors?: { name: string; hex?: string; image?: string }[];
  /** Extra fabric names. */
  fabrics?: string[];
  /** Rows merged into (or added as) named info sections, e.g. "dimensions". */
  sections?: { name: string; rows: { label: string; value: string }[] }[];
};

export const catalogOverrides: Record<string, CatalogOverride> = {};
